struct DigitLine: View {
    let text: String
    let size: CGFloat
    var cursor: Int? = nil
    var body: some View {
        HStack(alignment: .lastTextBaseline, spacing: 0) {
            ForEach(Array(text.enumerated()), id: \.offset) { index, char in
                if cursor == index { Rectangle().frame(width:1,height:size).accessibilityHidden(true) }
                if "0123456789".contains(char) { HPDigit(digit:char).frame(width:size * 0.61,height:size).accessibilityHidden(true) }
                else { Text(String(char)).font(.system(size:size,design:.monospaced)).fixedSize() }
            }
            if cursor == text.count { Rectangle().frame(width:1,height:size).accessibilityHidden(true) }
        }.accessibilityElement(children:.ignore).accessibilityLabel(text)
    }
}
